def _components(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy in (-1, 0, 1):
                    for dx in (-1, 0, 1):
                        if dy == dx == 0:
                            continue
                        ny, nx = y + dy, x + dx
                        if (0 <= ny < h and 0 <= nx < w and grid[ny][nx] != 0
                                and (ny, nx) not in seen):
                            seen.add((ny, nx))
                            q.append((ny, nx))
            r0 = min(y for y, x in cells)
            r1 = max(y for y, x in cells)
            c0 = min(x for y, x in cells)
            c1 = max(x for y, x in cells)
            mask = {(y-r0, x-c0) for y, x in cells}
            comps.append((len(cells), r1-r0+1, c1-c0+1, mask))
    return comps


def transform(grid):
    comps = _components(grid)
    # The two repeated panels have matching bounding-box dimensions.
    candidates = []
    for i in range(len(comps)):
        for j in range(i + 1, len(comps)):
            a, b = comps[i], comps[j]
            if a[1:3] == b[1:3]:
                candidates.append((a[0] + b[0], a, b))
    if not candidates:
        raise ValueError("Could not identify a matching pair of panels")
    _, a, b = max(candidates, key=lambda t: t[0])
    h, w = a[1], a[2]
    diff = {(r, c) for r in range(h) for c in range(w)
