    if not diff:
        return [[0]]
    r0 = min(r for r, c in diff)
    r1 = max(r for r, c in diff)
    c0 = min(c for r, c in diff)
    c1 = max(c for r, c in diff)
    return [[8 if (r, c) in diff else 0
             for c in range(c0, c1 + 1)]
            for r in range(r0, r1 + 1)]
